export function bindHandSwipe(ui){
 const host=ui.host;let gesture=null,suppressUntil=0;
 const cards=()=>[...host.querySelectorAll('.gd-hand-area [data-gcard]')];
 const stop=()=>{clearTimeout(gesture?.timer);if(gesture?.active||gesture?.scrolling)suppressUntil=Date.now()+650;gesture=null;host.classList.remove('hand-swiping')};
 const paint=index=>{const g=gesture,list=cards();if(!g||!g.active)return;if(list.map(b=>b.dataset.gcard).join(',')!==g.signature){stop();return}const scrollLeft=host.querySelector('.gd-hand-scroll')?.scrollLeft??0;for(let i=Math.min(g.last,index);i<=Math.max(g.last,index);i++){const b=list[i];if(!b||b.disabled)continue;const id=+b.dataset.gcard;if(g.visited.has(id))continue;g.visited.add(id);g.select?ui.selected.add(id):ui.selected.delete(id)}g.last=index;ui.choice=null;ui.render();const scroll=host.querySelector('.gd-hand-scroll');if(scroll)scroll.scrollLeft=scrollLeft};
 const down=e=>{const b=e.target.closest?.('.gd-hand-area [data-gcard]');if(!b||b.disabled||e.button!==0||!e.isPrimary||ui.game?.returns?.length)return;stop();const list=cards(),index=list.indexOf(b);gesture={signature:list.map(b=>b.dataset.gcard).join(','),pointer:e.pointerId,x:e.clientX,y:e.clientY,last:index,select:!ui.selected.has(+b.dataset.gcard),visited:new Set(),active:false,scroll:b.closest('.gd-hand-scroll'),scrollLeft:b.closest('.gd-hand-scroll')?.scrollLeft??0};const g=gesture;g.timer=setTimeout(()=>{if(gesture!==g||!host.contains(b)||b.disabled)return;g.active=true;host.setPointerCapture?.(g.pointer);host.classList.add('hand-swiping');paint(index)},280)};
 const move=e=>{const g=gesture;if(!g||e.pointerId!==g.pointer)return;if(!g.active){if(Math.hypot(e.clientX-g.x,e.clientY-g.y)>12){clearTimeout(g.timer);g.scrolling=true;if(g.scroll)g.scroll.scrollLeft=g.scrollLeft+g.x-e.clientX;suppressUntil=Date.now()+650}return}e.preventDefault();const list=cards();const hit=document.elementsFromPoint(e.clientX,e.clientY).map(n=>n.closest?.('[data-gcard]')).find(n=>list.includes(n));if(hit&&list.indexOf(hit)!==g.last)paint(list.indexOf(hit))};
 const end=e=>{if(gesture&&e.pointerId===gesture.pointer){if(gesture.active)e.preventDefault();stop()}};
 const click=e=>{if(Date.now()<suppressUntil&&e.target.closest?.('[data-gcard]')){e.preventDefault();e.stopImmediatePropagation()}};
 const context=e=>{if(e.target.closest?.('.gd-hand-area [data-gcard]'))e.preventDefault()};
 host.addEventListener('pointerdown',down);host.addEventListener('pointermove',move,{passive:false});host.addEventListener('pointerup',end);host.addEventListener('pointercancel',end);host.addEventListener('lostpointercapture',end);host.addEventListener('click',click,true);host.addEventListener('contextmenu',context);
 return()=>{stop();host.removeEventListener('pointerdown',down);host.removeEventListener('pointermove',move);host.removeEventListener('pointerup',end);host.removeEventListener('pointercancel',end);host.removeEventListener('lostpointercapture',end);host.removeEventListener('click',click,true);host.removeEventListener('contextmenu',context)};
}
